message.content:
{
  "css": ".itinerary {
  color: var(--ink);
}

/* Typography & Spacing */
.itinerary h2 {
  font-size: 16px;
  line-height: 22px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--ink);
}

.itinerary h2 span {
  font-weight: 500;
  color: var(--muted);
}

.itinerary .day-group:not(:last-child) {
  margin-bottom: 40px;
}

.itinerary .place-row:not(:last-child) {
  margin-bottom: 18px;
}

/* Card Surface & Structure */
.place-card {
  background-color: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  min-height: 96px;
  display: flex;
  align-items: center;
  overflow: hidden; /* Clips only the photo's own left corners */
}

/* Photo Styling */
.place-photo {
  width: 96px;
  height: 96px;
  object-fit: cover;
  flex-shrink: 0;
}

/* Copy Area */
.place-copy {
  min-width: 0;
  flex: 1;
  padding: 8px 12px;
  overflow-wrap: anywhere;
}

.place-title {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--ink);
  white-space: normal;
}

.place-region {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 500;
  color: var(--muted);
  margin-bottom: 4px;
  white-space: normal;
}

.place-type {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 500;
  color: var(--muted);
  white-space: normal;
}

/* Grip Icon */
.place-grip {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  margin-right: 6px;
  object-fit: contain;
}

/* Partial Fragment Slot */
.partial-slot {
  margin-left: 31px;
  height: 18px;
  overflow: hidden;
}

.partial-card {
  min-height: 96px;
  border: 1px solid var(--border);
  border-top-left-radius: 6px;
  border-bottom-left-radius: 6px;
  display: flex;
  align-items: center;
  background-color: #fff;
}

.partial-card img {
  width: 96px;
  height: auto;
  object-fit: cover;
}

/* Responsive Narrow Widths */
@media (max-width: 360px) {
  .place-photo {
    width: 72px;
    height: 72px;
  }

  .place-copy {
    padding: 8px;
  }
}"
}
